// Generated by Pen to Ink.
#include "NarrativeCuePlayer.h"
#include "NarrativeBridgeStoryData.h"
#include "Camera/CameraShakeBase.h"
#include "Camera/PlayerCameraManager.h"
#include "Components/AudioComponent.h"
#include "Engine/World.h"
#include "GameFramework/PlayerController.h"
#include "Kismet/GameplayStatics.h"
#include "Sound/SoundBase.h"

UNarrativeCuePlayerComponent::UNarrativeCuePlayerComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void UNarrativeCuePlayerComponent::OnRegister()
{
    Super::OnRegister();
    // The first time, list every cue in the story with a likely action.
    if (Cues.Num() == 0)
        for (const FString& Name : UNarrativeStoryData::DefaultInfo().Cues)
        {
            FNarrativeCueSetup Cue;
            Cue.Name = Name;
            Cue.Action = Guess(Cue.Name);
            Cues.Add(Cue);
        }
}

void UNarrativeCuePlayerComponent::BeginPlay()
{
    Super::BeginPlay();
    Story = GetOwner() ? GetOwner()->FindComponentByClass<UNarrativeBridgeComponent>() : nullptr;
    if (Story) Story->OnCue.AddDynamic(this, &UNarrativeCuePlayerComponent::HandleCue);
    else UE_LOG(LogTemp, Warning, TEXT("[NarrativeBridge] The Narrative Cue Player on %s has no Pen to Ink component next to it."), *GetNameSafe(GetOwner()));
}

void UNarrativeCuePlayerComponent::EndPlay(const EEndPlayReason::Type Reason)
{
    if (Story) Story->OnCue.RemoveDynamic(this, &UNarrativeCuePlayerComponent::HandleCue);
    Super::EndPlay(Reason);
}

void UNarrativeCuePlayerComponent::HandleCue(const FString& Name, const FString& Value)
{
    PlayCue(Name, Value);
}

void UNarrativeCuePlayerComponent::PlayCue(const FString& Name, const FString& Value)
{
    OnAnyCue.Broadcast(Name, Value);
    const FString Tag = Value.IsEmpty() ? Name : Name + TEXT(":") + Value;
    for (const FNarrativeCueSetup& Cue : Cues)
        if (Cue.Name.Equals(Name, ESearchCase::IgnoreCase)) Run(Cue, Value, Tag);
}

FString UNarrativeCuePlayerComponent::StorySound(const FString& Tag)
{
    for (const FNarrativeStoryCueSound& Sound : UNarrativeStoryData::DefaultInfo().CueSounds)
        if (Tag == Sound.Tag) return Sound.File;
    return FString();
}

USoundBase* UNarrativeCuePlayerComponent::PickSound(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag) const
{
    // The cue's own sound named by the value; else the writer's sound for this cue; else the cue's first sound.
    if (!Value.IsEmpty())
        for (USoundBase* S : Cue.Sounds)
            if (S && S->GetName().Equals(Value, ESearchCase::IgnoreCase)) return S;
    if (bPlayStorySounds)
        if (USoundBase* Writers = UNarrativeBridgeComponent::LoadVoiceClip(StorySound(Tag))) return Writers;
    for (USoundBase* S : Cue.Sounds)
        if (S) return S;
    return nullptr;
}

void UNarrativeCuePlayerComponent::Run(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag)
{
    switch (Cue.Action)
    {
    case ENarrativeCueAction::PlayMusic:
        // A music cue with no value stops the music.
        if (Value.IsEmpty()) StopMusic();
        else PlayMusic(PickSound(Cue, Value, Tag), Cue.Volume);
        break;
    case ENarrativeCueAction::StopMusic:
        StopMusic();
        break;
    case ENarrativeCueAction::PlaySound:
        if (USoundBase* Sound = PickSound(Cue, Value, Tag)) UGameplayStatics::PlaySound2D(this, Sound, Cue.Volume);
        break;
    case ENarrativeCueAction::PlayAmbience:
    {
        // An ambience cue with no value stops the ambience.
        if (Value.IsEmpty()) { if (Ambience) Ambience->Stop(); break; }
        USoundBase* Loop = PickSound(Cue, Value, Tag);
        if (!Loop || (Ambience && Ambience->Sound == Loop && Ambience->IsPlaying())) break;
        if (Ambience) Ambience->Stop();
        Ambience = UGameplayStatics::SpawnSound2D(this, Loop, Cue.Volume, 1.f, 0.f, nullptr, true, false);
        if (Ambience) Ambience->OnAudioFinished.AddDynamic(this, &UNarrativeCuePlayerComponent::HandleAmbienceFinished);
        break;
    }
    case ENarrativeCueAction::StopAmbience:
        if (Ambience) Ambience->Stop();
        Ambience = nullptr;
        break;
    case ENarrativeCueAction::ShakeCamera:
        Shake(Value.IsEmpty() ? 0.5f : FMath::Clamp(FCString::Atof(*Value), 0.f, 1.f));
        break;
    default:
        break;
    }
}

void UNarrativeCuePlayerComponent::HandleAmbienceFinished()
{
    // Ambience loops until another cue stops it.
    if (Ambience) Ambience->Play();
}

void UNarrativeCuePlayerComponent::PlayMusic(USoundBase* Sound, float Volume)
{
    if (!Sound || (Music && Music->Sound == Sound && Music->IsPlaying())) return;
    const float Half = MusicFade * 0.5f;
    if (Music) Music->FadeOut(Half, 0.f);
    Music = UGameplayStatics::SpawnSound2D(this, Sound, Volume, 1.f, 0.f, nullptr, true, true);
    if (Music && Half > 0.f)
    {
        Music->Stop();
        Music->FadeIn(Half, Volume);
    }
}

void UNarrativeCuePlayerComponent::StopMusic()
{
    if (Music) Music->FadeOut(MusicFade * 0.5f, 0.f);
    Music = nullptr;
}

USoundBase* UNarrativeCuePlayerComponent::GetCurrentMusic() const
{
    return Music && Music->IsPlaying() ? Music->Sound.Get() : nullptr;
}

void UNarrativeCuePlayerComponent::Shake(float Strength)
{
    if (!ShakeClass) return;
    APlayerController* Player = GetWorld() ? GetWorld()->GetFirstPlayerController() : nullptr;
    if (Player && Player->PlayerCameraManager) Player->PlayerCameraManager->StartCameraShake(ShakeClass, Strength);
}

ENarrativeCueAction UNarrativeCuePlayerComponent::Guess(const FString& Name)
{
    const FString N = Name.ToLower();
    if (N.Contains(TEXT("stop_music")) || N == TEXT("silence")) return ENarrativeCueAction::StopMusic;
    if (N.Contains(TEXT("stop_ambience"))) return ENarrativeCueAction::StopAmbience;
    if (N.Contains(TEXT("music")) || N == TEXT("song") || N == TEXT("track")) return ENarrativeCueAction::PlayMusic;
    if (N.Contains(TEXT("ambien")) || N == TEXT("weather")) return ENarrativeCueAction::PlayAmbience;
    if (N.Contains(TEXT("sound")) || N == TEXT("sfx")) return ENarrativeCueAction::PlaySound;
    if (N.Contains(TEXT("shake")) || N == TEXT("rumble")) return ENarrativeCueAction::ShakeCamera;
    return ENarrativeCueAction::EventOnly;
}
